// ramana_ta.dart
// ரமண மகரிஷி மேற்கோள்கள் மற்றும் கட்டுரைகள்

import '../articlesquotes.dart';

final ramanaSaintTa = Saint(
  'raman',
  'மகரிஷி ரமணர்',
  'assets/images/raman.jpg',
  [
    'உன் சொந்த ஆத்ம உணர்வே உலகிற்கு நீ செய்யும் உயர்ந்த சேவை.',
    'உருவாக்கமுமில்லை அழிவுமில்லை; விதியுமில்லை சுயச்செயலும் இல்லை; பாதையுமில்லை சாதனையும் இல்லை — இதுவே இறுதி உண்மை.',
    'மகிழ்ச்சி உன் இயல்பு. அதை நாடுவது தவறல்ல; அது உன்னுள் இருக்கும்போது வெளியில் தேடுவதுதான் தவறு.',
    '“நான் யார்?” என்ற கேள்வி மற்ற எல்லா கேள்விகளையும் அழித்துவிடும்.',
    'தன் உண்மை இயல்பை அறியாமல் உலகை மாற்ற நினைப்பது, கற்களும் முட்களும் குத்தாதிருக்க உலகம் முழுவதையும் தோலால் மூட முயல்வதைப் போன்றது.',
    'அமைதியும் ஒரு உரையாடல்.',
    'மனம் என்பது எண்ணங்களின் தொகுப்பு மட்டுமே. எண்ணங்களை நிறுத்தி மனதை காட்டு.',
    'இப்பிறவியின் உண்மையான பயன் உள்ளார்ந்து ஆத்மாவை உணர்வதே.',
    'முயற்சி இன்றி யாரும் வெற்றி பெறவில்லை; வெற்றி பெறுவோர் உறுதியான முயற்சிக்கே கடமைப்பட்டவர்கள்.',
    'வருவது வரட்டும்; போவது போகட்டும்; மீதமிருப்பதை அறிந்து கொள்.',
    '“நான் யார்?” என்பது வெறும் மனப்பயிற்சி அல்ல; அது உயர்ந்த ஆன்மிக சாதனை.',
    '“நான்” என்ற எண்ணமே மற்ற எல்லா எண்ணங்களின் வேர்; அதனை அதன் மூலத்திற்கு பின்தொடர்வதே எண்ணங்களை அழிக்கும் வழி.',
    'ஆத்மா எப்போதும் உள்ளது; அதை தேட வேண்டியதில்லை — ஆத்மமல்லாததைத் தேடுவதை நிறுத்தினால் போதும்.',
    'இறுதி உண்மை — “நான்” என்பது எண்ணம் அல்ல; அது சுத்த சித்தம்.',
    'ஆத்ம உணர்வுக்கு தேவையானது அமைதியில் நிலைத்திருப்பதே.',
    'நீயே ஆத்மா — அதுவாக இரு.',
    '“நான் யார்?” என கேட்பது மனதை உள்ளார நோக்கி அதன் மூலத்தில் ஆழ்த்துவது.',
    'கயிற்றில் பாம்பு தோன்றுவது போல, ஆத்மாவில் தான் அகங்காரம் தோன்றுகிறது.',
    'அகங்காரமே மனம்; மனமே ஆசைகளின் மூலாதாரம்.',
    'அகங்காரம் உண்மையானது அல்ல; அது ஆத்ம ஒளி உதித்தால் மறையும் நிழல்.',
    'மனம் மாயத் தோற்றம்; அது எண்ணங்களின் கூட்டம் மட்டுமே.',
    'மனம் அடங்கும் போது ஆத்மா வெளிப்படும்; மனமே தடையாகிறது.',
    'ஆத்ம உணர்வு புதிதாய் பெறுவது அல்ல; அது நித்திய இயல்பை மீண்டும் உணர்வதே.',
    'உடலும் மனமும் நீ அல்ல; அவற்றின் சாட்சி நீ.',
    '“நான்” எண்ணம் மறைந்தால் மற்ற எல்லா எண்ணங்களும் மறையும்.',
    'அமைதியே மிக வலிமையான ஆன்மிக உபதேசம்.',
    'நிசப்தத்தில் நிலைத்திருப்பதே உயர்ந்த சாதனை.',
    'உணர்வு என்பது அடைய வேண்டிய ஒன்று அல்ல; எண்ணங்கள் மறைந்தால் அது வெளிப்படும்.',
    'இதயத்தின் அமைதி எந்த பேச்சையும் விட ஆழமாகப் பேசுகிறது.',
    'உண்மையான ஞானம் புத்தியில் இல்லை; அது அமைதியில் வெளிப்படும் இதயத்தில் உள்ளது.',
    '“நான்” மற்றும் “நீ” இல்லாத அமைதியே இறுதி நிலை.',
    'முழு நிசப்த நிலையில் ஆத்மா உணரப்படுகிறது.',
    'அமைதியில் நிலைபெறுதலே உயர்ந்த பிரார்த்தனை.',
    'எண்ணமின்மையே உண்மையான அமைதி.',
    'தியானம் என்பது இறைவனை நினைப்பது அல்ல; இறைவனாகிய அமைதியில் இருப்பது.',
    'மனம் ஓயாத குரங்கு; அதை அடக்க வழி அமைதிதான்.',
    'அமைதியே ஆத்மாவின் நித்திய நிலை.',
    'அமைதியில் ஆழ்ந்தளவிற்கு உண்மை வெளிப்படும்.',
    'அமைதி என்பது சத்தமின்மை அல்ல; நிலைபெற்ற அமைதியின் இருப்பு.',
    'உண்மையான பிரார்த்தனை — அமைதியில் இருந்து “நான் இருக்கிறேன்” என்பதை அறிதல்.',
    'இறைவன் வெளிப்புற உயிரல்ல; இறைவன் ஆத்மா.',
    'உலகம் மாயை; ஆத்மா மட்டுமே நிஜம்.',
    'நீ காண்பதும் கேட்பதும் அனைத்தும் இறை வெளிப்பாடு.',
    'உலகம் மனத்தின் பிரதிபலிப்பு.',
    'ஆத்மாவைத் தவிர வேறு நிஜம் இல்லை.',
    'உலகம் உன்னிடமிருந்து தனியான ஒன்று அல்ல.',
    'பிரபஞ்சம் உன்னுள் உள்ளது; நீ அதற்குள் அல்ல.',
    'ஆத்மாவே ஒரே நிஜம்; உலகம், அகங்காரம், இறைவன் அனைத்தும் அதிலேயே.',
    'உலகம் கனவு; கனவு காண்பவன் ஆத்மா.',
    'இறைவன் அனைத்திற்கும் மூலமும் சாட்சியும் நிஜமும்.',
    'ஒரே நிஜம் — சுத்த சித்தம்.',
    'இறைவன் அன்பு; அன்பே ஆத்ம ஒளி.',
    'உலகம் ஒரு கருத்து; ஆத்மா மட்டுமே உண்மை.',
    'உலகம் இறை வெளிப்பாடு; ஆனால் இறைவன் உலகத்தால் கட்டுப்படுபவர் அல்ல.',
    'ஆத்மாவே எல்லா இருப்புகளின் அடித்தளம்.',
    'செயல் பந்தத்திற்கு காரணம் அல்ல; செய்கிறேன் என்ற உணர்வே காரணம்.',
    'உண்மையான செயல் முயற்சியற்றது; அது இருப்பின் நிலையிலிருந்து பாய்கிறது.',
    'செயலின் பலனைப் பற்றி கவலைப்படாதே; ஆத்மா அனைத்தையும் கவனிக்கும்.',
    'செய்கிறேன் என்ற உணர்வு இல்லாமல் செய்யும் செயல் விடுதலை தரும்.',
    'கர்மம் காரண-பலன் தொடர்; ஆத்மா அதற்கு அப்பாற்பட்டது.',
    'உலகில் வாழ்; உலகில் மூழ்காதே.',
    'கர்மத்திலிருந்து விடுபடும் வழி ஆத்ம உணர்வு.',
    'பலன் பற்றின்றி கடமைகளை செய்.',
    'இறை சித்தத்திற்கு சரணாகதி கொள்; செயல்கள் இயல்பாய் நடைபெறும்.',
    'ஆத்மாவை உணர்ந்தவனுக்கு கர்மம் இல்லை.',
    'இந்திரியங்களுக்கும் ஆசைகளுக்கும் அடிமையாவதைத் தவிர்.',
    'பிறரை சேவிக்கும் அளவிற்கு அவர்களுள் ஆத்மாவை உணர்வாய்.',
    'செயல்களுக்கு சாட்சியாக இருப்பதே உயர்ந்த செயல்.',
    'செயல் எண்ணத்திலிருந்து பிறக்கிறது; அமைதி இரண்டையும் கடக்கிறது.',
    'உலகம் மேடை; பாத்திரத்தை நடி — நீ யார் என்பதை மறந்துவிடாதே.',
    'குரு மனிதன் அல்ல; குரு ஆத்மா.',
    'குரு உன்னுள் உள்ளார்; அவர் உள்நாதம்.',
    'உண்மையான குரு உன்னை ஆத்மாவிற்கு நடத்துபவர்.',
    'குரு அருள் எப்போதும் உள்ளது; அதை ஏற்குவது உன் பொறுப்பு.',
    'குருவை மதிக்கும் சிறந்த வழி ஆத்ம உணர்வு.',
    'குரு உன் உண்மை உருவத்தை காட்டும் கண்ணாடி.',
    'ஆத்ம உணர்வுக்கு குரு அருள் அவசியம்.',
    'குரு உடல் அல்ல; எல்லா இதயங்களிலும் நிறைந்த சித்தம்.',
    'குரு வழிகாட்டி; வழங்குபவர் அல்ல.',
    'குரு அருள் காற்று; உன் முயற்சி பறக்கை.',
    'குருவில் நம்பிக்கை வைய்; அவர் உண்மைக்கு வழி காட்டுவார்.',
    'குரு உண்மையின் உயிர் உருவம்.',
    'குரு உன்னிடம் இருந்து பிரிந்தவர் அல்ல; நீயும் குருவும் ஒன்றே.',
    'குருவின் உபதேசம் — அமைதியில் இரு.',
    'மனதைத் தாண்டிச் செல்ல உதவுபவர் குரு.',
    'மனம் செயல்படும் அகங்காரம்.',
    'அகங்காரம் — “நான் உடல்” என்ற உணர்வு.',
    'அகங்காரம் மறைந்தால் ஆத்ம ஒளி வெளிப்படும்.',
    'ஆத்ம உணர்வின் மிகப்பெரிய தடையாக அகங்காரம் உள்ளது.',
    'அகங்காரம் எண்ணங்கள், உணர்வுகள், நினைவுகள் சேர்க்கை.',
    'மனம் நல்ல பணியாளர்; ஆனால் ஆபத்தான அதிபதி.',
    'விடுதலை வேறு இடத்திற்குச் செல்வது அல்ல; இங்கே இப்போது இருப்பதே.',
    'அகங்காரத்தை அழிக்கும் வழி ஆத்ம சரணாகதி.',
    'மனம் மோசடிக்காரன்; தனித்த சுயம் என்ற மாயையை உருவாக்குகிறது.',
    'அகங்காரம் பயமும் ஆசையும் கட்டிய கோட்டை.',
    'சுதந்திரம் — மனத்திலிருந்து விடுதலை.',
    'மனம் கண்ணாடி; அதில் காண்பது உன் எண்ணங்களின் பிரதிபலிப்பு.',
    'மனம் துன்பத்தின் மூலமும் ஆத்மா ஆனந்தத்தின் மூலமும்.',
    'அகங்காரம் எல்லா பிரச்சினைகளின் வேர்; அது “எனக்கு வேண்டும்” என்கிறது.',
    'மனம் கனவுகள் உருவாக்கும் கருவி; உலகையும் அதன் மாயைகளையும் படைக்கிறது.',
    'மனம் நதி; ஆத்மா சமுத்திரம்.',
    'விடுதலை இலக்கு அல்ல; இருப்பின் நிலை.',
    'மனம் கருவி; அதை பயன்படுத்துபவன் நீ.',
    'அகங்காரம் நாம் நமக்கே சொல்வது ஒரு கதை.',
    'மனம் சிறை; ஆத்மா திறவுகோல்.',
    'மனம் ஆத்ம சூரியனை மறைக்கும் மேகம்.',
    'அகங்காரம் தற்காலிக மாயை; ஆத்மா நித்திய உண்மை.',
    'மனம் விருந்தினர்; ஆத்மா எஜமான்.',
    'விடுதலை பூரண அமைதியின் நிலை.',
    'சுதந்திரம் பெற ஒரே வழி — நீயாக இரு.',
    '“நான் யார்?” என்ற கேள்வி பதில் பெற அல்ல; கேள்வியே பதில். “நான்” எண்ணத்தின் மூலத்தை ஆராய்ந்தால் பொய்யான நான் மறைந்து உண்மை ஆத்மா தானாக வெளிப்படும்.',
    'உன் கடமை இருப்பதே; இதோ அதோ ஆகுவது அல்ல. “நான் இருப்பவன் நான்” — இதுவே முழு உண்மை. முறை — அமைதியில் நிலைபெறு; அதாவது பெயரும் உருவமும் எனும் மாயையை அழி.',
    'ஆத்மா எப்போதும் உள்ளது — அதுவே நீ. அதை அடைய வேண்டியதில்லை; ஆத்மமல்லாத எண்ணத்தை விட்டுவிட வேண்டும்.',
    'தனித்த தன்மை எண்ணம் இருக்கும் வரை உலகமும் இறைவனும் தோன்றும்; அது மறைந்தால் அனைத்தும் மறையும்.',
    'மகிழ்ச்சி உன் இயல்பு; அதை வெளியில் தேடுவது தவறு.',
    'மனம் எண்ணங்களின் கூட்டம்; “நான்” எண்ணமே அதன் வேர். வேரை பிடுங்கினால் அனைத்தும் நீங்கும்.',
    'மனம் நிறுத்தப்படும் போது ஆத்மா வெளிப்படும்; மனம் இருக்கும் வரை சந்தேகமும் துன்பமும் இருக்கும்.',
    'அமைதியே மிக வலிமையான போதனை; எல்லா சந்தேகங்களும் அமைதியில் தீரும்.',
    'ஆத்மா அடைய வேண்டிய ஒன்று அல்ல; நீ எப்போதும் அதுவே. அறியாமை நீங்கினால் போதும்.',
    'மனம் உள்ளார்ந்து தன் இயல்பை ஆராயும் போது அது மறைந்து ஆத்மா மட்டும் மீறும்.',
    'நாம் நிஜமே ஆனபோதும் நிஜத்தை அடைய முயல்வதே மிகப்பெரிய அதிசயம்.',
    'உடலும் உலகமும் எண்ணங்கள்; மனம் மறைந்தால் எண்ணங்களும் மறையும்.',
    'அருள் எப்போதும் உள்ளது; அது புதிதாய் பெறப்படுவது அல்ல — அதுவே ஆத்மா.',
    'ஆத்ம உணர்வை அடைய வேண்டியதாக நினைப்பதே மிகப்பெரிய தடையாகும்.',
    'ஆத்மாவை அடைய முயலாதே; அதை மறைக்கும் தடைகளை நீக்கு.',
    'மனம் மனதை அழிக்க முடியாது; அது மூலத்தில் கரைந்தால் மட்டுமே மறையும்.',
    'ஆத்ம விசாரணை “நான் யார்?” என்ற மந்திரம் அல்ல; “நான்” உணர்வில் கவனம் நிலைநிறுத்துவது.',
    'அகங்காரம் நிழல்; அதைத் தேடினால் அது மறையும்.',
    'அகங்காரம் மறைந்தால் ஆனந்தமான ஆத்மா மட்டும் மீறும்.',
    'உணர்வு என்ற தனி நிகழ்வு இல்லை; அறியாமை நீங்குதலே அது.',
    'ஆத்மா எப்போதும் உள்ளது; தடையாக இருப்பது ஓயாத மனம்.',
    'அமைதியில் நிலைத்திருப்பதே ஞானத் தெளிவு.',
    'எதை செய்தாலும் “நான்” உணர்வை ஆராய வேண்டும் — அதுவே வழி.',
    'எண்ணமின்றி ஆத்மாவாக நிலைத்தால் அனைத்து பிரச்சினைகளும் தானாக மறையும்.',
    '“நான்” உணர்வு உடலில் தோன்றினாலும் உடலுக்குச் சேர்ந்தது அல்ல.',
    'வெளி நோக்கும் மனம் எண்ணங்களாகும்; உள்ளார நோக்கும் மனம் ஆத்மாவாகும்.',
    'உலகம் உன்னுக்கு வெளியே இல்லை; அது மனத்தின் வெளிப்பாடு.',
    'மனம் அமைதியானால் உலகமும் அமைதியாகத் தோன்றும்.',
    'மனத்தை கட்டுப்படுத்துவது அல்ல; அதன் இயல்பை ஆராய்வதே அவசியம்.',
    '“நான் உடல்” என்று நினைக்கும் வரை துன்பம் நீங்காது.',
    'ஆத்மா புத்தியால் அறியப்படாது; புத்தி அடங்கும் போது வெளிப்படும்.',
    '“நான்” எண்ணம் மறைந்தால் ஆத்மா மட்டும் மீறும்.',
    '“நான்” எண்ணம் காவலாளியாக நடித்த திருடன் போன்றது.',
    'ஆத்மா வருவதுமில்லை போவதுமில்லை; எண்ணங்களே வருகின்றன போகின்றன.',
    'உணர்வு நிலை இயல்பான நிலை.',
    'உலகத்தைத் துறக்க வேண்டியதில்லை; உலகை தனித்ததாக காணும் அகங்காரத்தைத் துற.',
    'உடலும் மனமும் கருவிகள்; நீ அவை அல்ல.',
    'சுதந்திரம் வெளியே இல்லை; பொய்யான “நான்” இலிருந்து விடுதலை.',
    'ஆத்மா அனுபவிக்கப்படும் பொருள் அல்ல; அனுபவிப்பவன் அதுவே.',
    'விசாரணை அமைதிக்கு வழி; அமைதி உண்மையை வெளிப்படுத்தும்.',
    'பொருள்களில் பற்றிய மனம் பந்தம்; பற்றற்ற மனம் சுதந்திரம்.',
    'முயற்சியும் அருளும் வேறல்ல.',
    'முழு சரணாகதி ஏற்பட்டால் கேள்வி கேட்பவன் இல்லை.',
    'சிறந்த சாதனை ஆத்ம விசாரணை.',
    'ஆத்மா மட்டுமே உள்ளது; மற்றவை தோற்றம்.',
    'அகங்காரம் பொருள்களோடு ஒட்டியே வாழ்கிறது; ஒட்டுதல் நீங்கினால் அது மறையும்.',
    'ஆத்மா உள்ளும் வெளியும் அல்ல; அது மட்டுமே உள்ளது.',
    'பிறந்தது அழியும்; உண்மை பிறக்காது.',
    'ஆத்மாவாக நிலைநிற்றல் உயர்ந்த தியானம்.',
    '“நான் யார்?” என கேட்பது மனத்தை உள்ளார நோக்கி திருப்புவது.',
    'செய்கிறேன் என்ற உணர்வே பந்தம்.',
    'நான் செய்பவன் அல்ல என உணர்ந்தால் செயல்கள் தொடரும்; பந்தம் இல்லை.',
    'அமைதியே உன் உண்மை இயல்பு.',
    'ஆசையின்மை ஞானம்.',
    'ஆத்மாவுக்கு பாதுகாப்பு தேவையில்லை.',
    'நிலையற்றவற்றோடு ஒன்றிப்பதே துன்பத்தின் காரணம்.',
    'ஆத்மா விழிப்பு, கனவு, நித்திரை நிலைகளின் சாட்சி.',
    'நித்திரை ஆனந்தம் தருவது அகங்காரம் இல்லாததால்.',
    'நித்தியமானது இழக்கப்படாது.',
    'வெளியில் மகிழ்ச்சி தேடும் மனம் அதை ஒருபோதும் காணாது.',
    'உண்மை எளிமையானது; மனம் அதை சிக்கலாக்குகிறது.',
    'தேடுபவன் தேடப்படுபவனே.',
    'அகங்காரத்தைத் தவிர தனி அறியாமை இல்லை.',
    'அகங்காரம் மறைந்தால் ஆத்மா ஒளிரும்.',
    'மனம் ஆத்மாவிலிருந்து விலகிய இயக்கம் மட்டுமே.',
    'அமைதியில் இரு; நீயே ஆத்மா என்பதை அறி.',
    'ஆத்மா தானே ஒளிர்கிறது.',
    'விசாரணை அறியாமையை அழிக்கிறது.',
    'உடலுக்கு ஏற்படும் எதுவும் ஆத்மாவை பாதிக்காது.',
    'விடுதலை எதிர்காலத்தில் அல்ல; இப்போதுதான்.',
    'அகங்காரம் பந்தம்; ஆத்மா சுதந்திரம்.',
    'மனம் ஆத்மாவில் ஓய்வெடுக்கும் போது அதுவே உண்மையான துறவு.',
    'ஆத்மா மட்டுமே உண்மை; அகங்காரம் மாயை.',
    '“நான் உடல்” என்ற எண்ணமே முதற் அறியாமை.',
    'மற்ற அனைத்தும் நீங்கினாலும் ஆத்மா நிலைத்திருக்கும்.',
    'தியானம் — ஆத்மாவாக இருப்பது மட்டுமே.',
    'இதயம் உடல் இடம் அல்ல; சித்தத்தின் மூலாதாரம்.',
    'அனைத்து சாதனைகளும் மனத்தை அமைதிப்படுத்தவே.',
    'உண்மையான ஞானம் அமைதி.',
    'ஆத்மா எப்போதும் உணரப்பட்டதே.',
    'நீ கட்டுப்பட்டவன் அல்ல; அப்படியே நினைக்கிறாய்.',
    '“நான்” மூழ்கினால் ஆத்மா உதிக்கும்.',
    'ஆத்மா மட்டுமே உள்ளது; வேறு ஒன்றும் இல்லை.',
    'ஆகுதல் இல்லை; இருப்பதே உள்ளது.',
    'ஆத்மா காலத்தைத் தாண்டியது.',
    'ஆத்மாவை அறிதல் அதுவாக இருப்பதே.',
    'ஆத்மா சுத்த விழிப்புணர்வு.',
    'ஆத்மாவில் கரைந்த மனம் மீண்டும் எழாது.',
    'விசாரணையே நேரடி வழி.',
    'அகங்காரம் ஆத்மா மற்றும் உடலுக்கிடையிலான முடிச்சு.',
    'சுதந்திரம் அகங்காரத்திலிருந்து விடுதலை.',
    'மனம் அடங்கும் போது அமைதி நிலைக்கும்.',
    'ஆத்மா அறியப்பட வேண்டியது அல்ல; அதுவாக இருக்க வேண்டியது.',
    'ஆத்மா எப்போதும் அடைந்ததே.',
    'அகங்காரம் மறைவதே ஆத்ம உணர்வு.',
    'நீ இருப்பதைப் போலவே இரு.',
    'இருப்பதே உயர்ந்த உபதேசம்.',
    'ஆத்மா அனைவரிலும் ஒன்றே.',
    'உண்மை — நீ ஏற்கனவே சுதந்திரன்.',
    'ஆத்மாவில் நிலைபெறு; அனைத்தும் நன்றாகும்.'
  ],
  [
    Article(
        heading: 'மகாரிஷி ராமணரின் போதனைகள்',
        body: 'மகிழ்ச்சி\n\nஅனைத்து உயிர்களும் எப்போதும் மகிழ்ச்சியை விரும்புகின்றன, துன்பத்தின் ஒரு துளியும் இல்லாத மகிழ்ச்சியை. அதே நேரத்தில் ஒவ்வொருவரும் தன்னை மிகவும் நேசிக்கிறார். மகிழ்ச்சியின் காரணம் மகிழ்ச்சியே. எனவே, அந்த மகிழ்ச்சி ஒருவரிடமே இருக்க வேண்டும். மேலும், அந்த மகிழ்ச்சி தினமும் அனைவரும் ஆழ்ந்த தூக்கத்தில் அனுபவிக்கிறது, அங்கு மனம் இல்லை. இயல்பான மகிழ்ச்சியைப் பெற, ஒருவர் தன்னை அறிய வேண்டும். அதற்கு, “நான் யார்?” என்ற விசாரணை முதன்மையான வழிமுறை.\n\nவிழிப்புணர்வு\n\nஇருப்பு அல்லது விழிப்புணர்வே ஒரே யதார்த்தம். விழிப்புணர்வு கூடுதலாக விழித்திருப்பது விழித்திருப்பதை அழைக்கிறோம். விழிப்புணர்வு கூடுதலாக தூக்கம் தூக்கத்தை அழைக்கிறோம். விழிப்புணர்வு கூடுதலாக கனவு கனவை அழைக்கிறோம். விழிப்புணர்வு அனைத்து படங்களும் வரும் மற்றும் போகும் திரை. திரை உண்மை, படங்கள் வெறும் நிழல்கள் அதில்.\n\nமனம்\n\nமனம் சுயத்தில் உள்ள ஒரு அற்புதமான சக்தி.\n\nஇந்த உடலில் ‘நான்’ என்று எழுகிறது மனம்.\n\nசூட்சும மனம் மூளை மற்றும் உணர்வுகளின் மூலம் வெளிப்படும் போது, மூல நாமங்கள் மற்றும் வடிவங்கள் அறியப்படுகின்றன. இது இதயத்தில் இருக்கும் போது நாமங்கள் மற்றும் வடிவங்கள் மறைந்துவிடுகின்றன… இது இதயத்தில் இருக்கும் போது, ‘நான்’ அல்லது அகங்காரம், அனைத்து எண்ணங்களின் மூலமானது போய்விடும், மற்றும் சுயம், உண்மை, நித்திய ‘நான்’ மட்டுமே பிரகாசிக்கும். அகங்காரத்தின் சிறிய சுவடு இல்லாத இடத்தில் சுயம் உள்ளது.\n\n“நான் யார்?” – விசாரணை\n\nஅனைத்து எண்ணங்களுக்கும் மூலம் ‘நான்’ எண்ணம்.\n\nமனம் “நான் யார்?” என்ற சுய விசாரணையால் மட்டுமே கரையும். “நான் யார்?” என்ற எண்ணம் அனைத்து மற்ற எண்ணங்களையும் அழித்துவிட்டு, இறுதியில் தன்னையும் கொல்லும். மற்ற எண்ணங்கள் எழும்போது, அவற்றை முழுமையாக்க முயலாமல், எந்த எண்ணம் எழுந்தது என்பதை விசாரிக்க வேண்டும். அது முக்கியமில்லை எத்தனை எண்ணங்கள் எழுகின்றன. ஒவ்வொரு எண்ணமும் எழும்போது, எந்த எண்ணம் எழுகிறது என்பதை கவனமாகக் கேட்க வேண்டும். பதில் வரும்: “எனக்கு”. பின்னர் “நான் யார்?” என்று விசாரிக்கும் போது, மனம் அதன் மூலத்திற்கு திரும்பும்; மற்றும் எழுந்த எண்ணம் அமைதியாகிவிடும். இந்த வழியில் மீண்டும் மீண்டும் பயிற்சி செய்யும் போது, மனம் அதன் மூலத்தில் இருக்கும் சக்தியை அதிகரிக்கிறது.\n\nசரணாகதி\n\nசரணாகதியை அடைய இரண்டு வழிகள் உள்ளன. ஒன்று ‘நான்’ இன் மூலத்தைப் பார்த்து அதில் ஒன்றிணைவது. மற்றொன்று ‘நான் தனித்து உதவியற்றவன், கடவுள் மட்டுமே அனைத்து சக்தியும், எனக்கு பாதுகாப்பிற்கு வேறு வழி இல்லை’ என்று மனதில் உறுதியாக்கி, கடவுள் மட்டுமே இருக்கிறார் என்ற நம்பிக்கையை படிப்படியாக வளர்த்துக்கொள்வது. இரண்டு வழிகளும் ஒரே இலக்குக்கு இட்டுச் செல்கின்றன. முழுமையான சரணாகதி ஞானம் அல்லது விடுதலையின் மற்றொரு பெயர்.\n\nமூன்று நிலைகள்: விழித்திருப்பு, கனவு, மற்றும் தூக்கம்\n\nகனவு மற்றும் விழித்திருப்பு நிலைக்கு இடையில் வேறுபாடு இல்லை, கனவு குறுகியது மற்றும் விழித்திருப்பு நீண்டது. இரண்டும் மனத்தின் விளைவு. எங்கள் உண்மையான நிலை விழித்திருப்பு, கனவு மற்றும் தூக்க நிலைகளுக்கு அப்பால், துரியா என்று அழைக்கப்படுகிறது.\n\nஸ்ரீ ராமண மகாரிஷிGrace and Guru\n\nநான் குரு தேவையில்லை என்று சொல்லவில்லை. ஆனால் ஒரு குரு எப்போதும் மனித வடிவத்தில் இருக்க வேண்டியதில்லை. முதலில் ஒரு நபர் தன்னை குறைந்தவன் என்று நினைக்கிறான், மற்றும் ஒரு மேலான, அனைத்தையும் அறிந்த, அனைத்து சக்தியும் கொண்ட கடவுள் இருக்கிறார், அவர் தனது மற்றும் உலகின் விதியை கட்டுப்படுத்துகிறார், மற்றும் அவரை வழிபடுகிறார் அல்லது பக்தி செய்கிறார். அவர் ஒரு குறிப்பிட்ட கட்டத்தை அடைந்து விழிப்புணர்வுக்கு தகுதி பெறும் போது, அதே கடவுள் அவர் வழிபட்ட கடவுள் குருவாக வருகிறார் மற்றும் அவரை முன்னோக்கி வழிநடத்துகிறார். அந்த குரு வருகிறார் ‘அந்த கடவுள் உன்னுள் இருக்கிறார். உள்நோக்கி மூழ்கு மற்றும் உணரு’ என்று சொல்ல. கடவுள், குரு மற்றும் சுயம் ஒன்றே.\n\nசுய உணர்வு\n\nநாங்கள் அழைக்கும் உணர்வு நிலை எளிமையாக ஒன்றை இருப்பது, எதையும் அறியாமல் அல்லது எதையும் ஆகாமல். ஒருவர் உணர்ந்தால், அவர் அதுவே, எப்போதும் இருந்தது. அவர் அதை விவரிக்க முடியாது. அவர் அதுவாக இருக்க வேண்டும். நிச்சயமாக நாங்கள் தவறாக சுய உணர்வைப் பயன்படுத்துகிறோம், அதற்கு சிறந்த சொல் இல்லாததால்.\n\nஅனைத்தும் நாம் செய்ய வேண்டியது அமைதியாக இருப்பது. அமைதி எங்கள் உண்மையான இயல்பு. நாங்கள் அதை கெடுக்கிறோம். தேவையானது அதை கெடுப்பதை நிறுத்துவது.\n\nஇதயம்\n\nஇதயத்தின் குகையின் மையத்தில் ஒரே பிரம்மம் சுயமாக சுயமாக பிரகாசிக்கிறது, ‘நான்’-‘நான்’ என்ற உணர்வில். உன் உள்நோக்கி மூழ்கி இதயத்தை அடை, மூச்சு கட்டுப்பாட்டுடன் அல்லது சுயத்தின் விசாரணையில் மனம் குவிக்கப்பட்டதுடன். இவ்வாறு நீ சுயத்தில் நிலைநிறுத்தப்படுவாய்.\n\nதுறவு\n\nகிரிஹஸ்தா (குடும்பக்காரர்) மோக்ஷா (விடுதலை) திட்டத்தில் எவ்வாறு வாழ்கிறார் என்று கேட்கப்பட்டது. பகவான் சொன்னார், ‘நீ ஏன் உன்னை கிரிஹஸ்தா என்று நினைக்கிறாய்? சன்யாஸி (துறவி) ஆக வெளியே சென்றால், ஒத்த எண்ணம் உன்னை சன்யாஸி என்று வேலை செய்யும். நீ குடும்பத்தில் தொடர்ந்தாலும் அல்லது அதை விட்டுவிட்டு காட்டிற்குச் சென்றாலும், உன் மனம் உன்னுடன் செல்கிறது. அகங்காரம் எல்லா எண்ணங்களின் மூலம். அது உடலை மற்றும் உலகை உருவாக்கி, உன்னை கிரிஹஸ்தா என்று நினைக்க வைக்கிறது. நீ உலகத்தை துறந்தால், அது குடும்பத்தின் சூழல்களுக்கு காட்டின் சூழல்களை மட்டுமே மாற்றும். ஆனால் மனத் தடைகள் அதே இருக்கும். அவை புதிய சூழல்களில் கூட அதிகரிக்கும். சூழல் மாற்றத்தில் உதவி இல்லை. தடை மனம். அது குடும்பத்தில் அல்லது காட்டில் இருந்தாலும் அதை கடக்க வேண்டும். நீ காட்டில் செய்ய முடிந்தால், இப்போது ஏன் செய்ய முடியாது? எனவே, ஏன் உன் சூழலை மாற்று. உன் முயற்சிகள் இப்போது செய்யப்படலாம் - நீ இப்போது எந்த சூழலிலும் இருக்கிறாய். உன் சூழல் உன் விருப்பத்திற்கு ஒருபோதும் மாறாது’.\n\nவிதி மற்றும் சுதந்திரம்\n\nசுதந்திரம் மற்றும் விதி எப்போதும் இருக்கின்றன. விதி முந்தைய செயலின் விளைவு; அது உடலைப் பற்றியது. உடல் எவ்வாறு விரும்பினாலும் செய்யட்டும். ஏன் அதைப் பற்றி கவலை கொள்கிறாய். ஏன் அதை கவனிக்கிறாய். சுதந்திரம் மற்றும் விதி உடல் இருக்கும் வரை நீடிக்கும். ஆனால் ஞானம் இரண்டையும் தாண்டுகிறது. சுயம் அறிவுக்கும் அறியாமைக்கும் அப்பால். எதுவும் நடந்தாலும், அது ஒருவரின் முந்தைய செயல்களின் விளைவு, தெய்வ விதி மற்றும் பிற காரணிகளின் விளைவு.\n\nவிதியை வெல்ல அல்லது அதிலிருந்து சுதந்திரமாக இருக்க இரண்டு வழிகள் மட்டுமே உள்ளன. ஒன்று விதி யாருக்கு என்று விசாரித்து, சுயத்திற்கு மட்டுமே விதி இருக்கிறது, சுயம் அல்ல என்று கண்டறிந்து, அகங்காரம் விதியால் கட்டப்பட்டது என்று கண்டறிந்து. மற்ற வழி கடவுளிடம் முழுமையாக சரணாகதி செய்து, ஒருவரின் உதவியற்றதை உணர்ந்து, எப்போதும் ‘நான் அல்ல, கடவுளே’ என்று சொல்லி, ‘நான்’ மற்றும் ‘எனது’ என்ற எண்ணத்தை முழுமையாகக் கைவிட்டு, கடவுள் உன்னை என்ன செய்ய விரும்புகிறார் என்று அவரிடம் விட்டுவிடுவது. விதியை வெல்ல அகங்காரத்தின் முழுமையான ஒழிப்பு தேவை, நீ சுய விசாரணையால் அல்லது பக்தி மார்க்கத்தால் அடைந்தாலும்.\n\nஞானி\n\nஞானி வாழ்க்கையில் விடுதலை அடைந்துள்ளார், இங்கே இப்போதே. அது அவனுக்கு முக்கியமில்லை எவ்வாறு, எங்கே மற்றும் எப்போது உடலை விட்டுவிடுவது. சில ஞானிகள் துன்பப்படுவதாக தோற்றமளிக்கலாம், மற்றவர்கள் சமாதியில் இருக்கலாம், மேலும் சிலர் மரணத்திற்கு முன் பார்வையிலிருந்து மறையலாம். ஆனால் அது அவரது ஞானத்தில் வேறுபாடு இல்லை. அந்த துன்பம் தோற்றமானது, ஞானிக்கு உண்மையெனத் தோன்றுகிறது, ஆனால் அவனால் உணரப்படாது, ஏனெனில் அவன் ஏற்கனவே சுயத்துடன் அடையாளத்தை தாண்டியுள்ளான்.\n\nஞானி உடல் என்று நினைக்கவில்லை. அவன் உடலைப் பார்க்கவில்லை. அவன் உடலில் சுயத்தை மட்டுமே பார்க்கிறான். உடல் இல்லையெனில், அது எந்த வடிவிலும் மறைவது என்ற கேள்வி எழவில்லை.\n\nஸ்ரீ ராமண மகாரிஷி ராபிட்டுடன் பயிற்சி, அர்ப்பணம் மற்றும் பக்தி\n\nஸ்ரீ ராமண மகாரிஷியின் வாழ்க்கை மற்றும் போதனைகளின் ஒளியில், அருணாசல அஸ்ராம் தேவாலயத்தின் தேவாலயங்கள் ஆன்மீக பயிற்சி (சாதனா) அவசியம் என்று நம்புகின்றன. அமைதி, மகிழ்ச்சி மற்றும் அமரத்துவம் தியானம் மற்றும் சுய விசாரணையின் பயிற்சியில் தங்களை அர்ப்பணித்த ஆர்வலர்களுக்கு கிடைக்கும். குருவின் அருள் எப்போதும் இருக்கிறது, ஆனால் இந்த அருள் மிகவும் அனுபவிக்கப்படுகிறது சில உண்மையான சாதகர்களால் மட்டுமே, அவர்கள் தங்கள் வாழ்க்கையை போதனைகளின் பயிற்சிக்கு அர்ப்பணிக்கின்றனர்.\n\nநாங்கள் நம்புகிறோம் ஸ்ரீ ராமண மகாரிஷி தனது காலத்திற்கு மட்டுமே வாழ்ந்ததில்லை. அவரது இருப்பு மற்றும் வழிகாட்டல் இப்போது உடல் இருப்பில் இருந்தபோது போலவே அனுபவிக்கப்படலாம். அவரிடம் உண்மையான ஆர்வம் மற்றும் ஏக்கத்துடன் திரும்புபவர்கள், அவரது போதனைகளைப் பயன்படுத்த முயற்சிக்கும் அவர்கள், அவரது அருள் மற்றும் வழிகாட்டலை உணர்வார்கள். அதில் சந்தேகம் இல்லை.\n\nஅருணாசல அஸ்ராம் தேவாலயத்தில் பகவான் ஸ்ரீ ராமண மகாரிஷி ஆசான் மற்றும் குருவாக இருக்கிறார். உரைகள் மற்றும் விவாதங்கள் ஒரு ஆர்வலரின் வாழ்க்கையில் இடம் இருக்கலாம், ஆனால் அருணாசல அஸ்ராம் தேவாலயம் ஒரு வழியில் பராமரிக்கப்படுகிறது, இது பார்வையாளர்கள் மற்றும் குடியிருப்பாளர்கள் ஸ்ரீ ராமண மகாரிஷியின் போதனைகளை அமைதியில் உறிஞ்ச அனுமதிக்கிறது. அவரது போதனைகள் எப்போதும் அமைதியில் விநியோகிக்கப்படுகின்றன, மற்றும் அவற்றை கேட்க நாங்கள் எங்கள் மனதை அமைதிப்படுத்த வேண்டும். உரைகள் மற்றும் விவாதங்கள் அவரது அமைதியான போதனையை மறைக்கலாம்.\n\n“அமைதி அனைத்து மதங்களின் அனைத்து நதிகளும் வழிந்து செல்லும் கடல்.”\n\n— தயுமானவர்\n\nகுரு\n\nஸ்ரீ மகாரிஷி சொன்னார் ஒரு குரு தேவை என்று. அவர் மேலும் சொன்னார் குரு வெளிப்புறமாக இருக்காது, அவரது வழக்கில். மீண்டும், அவரது உடல் மரணத்திற்குப் பிறகு அவர் உடலுடன் அடையாளம் கொள்ளவில்லை என்று சொன்னார்; அதாவது அவர் இப்போது இருக்கிறார்.\n\nஉண்மை என்னவென்றால், எவரும் எங்களுக்கு விடுதலை தர முடியாது. வழி சுட்டிக்காட்டப்படலாம், திசைகள் தரப்படலாம். எங்கள் தீவிர ஏக்கம் மற்றும் முழு அர்ப்பணம் இலக்குக்கு மிகவும் அவசியமான காரணி. நாங்கள் ஒரு விஷயத்தில் மட்டுமே மூழ்கினால் - உண்மையை உணர்வது - உண்மை, ஒரு உடல் குரு (தேவைப்பட்டால்) மற்றும் அனைத்தும் தானாக எங்களுக்கு வரும். குரு நாங்கள் தயாரானபோது எங்களுக்கு வருவார். நாங்கள் தங்களை தயார்படுத்துவதில் கவனம் செலுத்த வேண்டும், மற்றவை தானாக.\n\nஸ்ரீ ராமண மகாரிஷியின் வாழும் இருப்பில் நம்பிக்கை கொண்டவர்களுக்கு இதில் சந்தேகங்கள் இல்லை.'
    ),
    Article(
        heading: 'யோகத்தின் எட்டு கிளைகள் ராமண மகாரிஷியால்',
        body: 'டி: ஞானத்தின் எட்டு கிளைகள் (ஞான அஷ்டாங்கா) என்ன?\n\nஎம்: எட்டு கிளைகள் முன்பு குறிப்பிடப்பட்டவை, வேறு வழியில் வரையறுக்கப்பட்டவை:\n\n(1) யமா: இது உணர்வுகளின் கூட்டத்தை கட்டுப்படுத்துவது, உடல் போன்ற உலகில் இருக்கும் குறைகளை உணர்வது.\n\n(2) நியமா: இது சுயத்துடன் தொடர்புடைய மன மோடுகளை பராமரிப்பது மற்றும் எதிரான மோடுகளை நிராகரிப்பது. வேறு வழியில், இது உயர்ந்த சுயத்திற்கு தொடர்ந்து எழும் அன்பு.\n\n(3) ஆசனா: இதன் உதவியுடன் பிரம்மத்தில் நிலையான தியானம் எளிதாக செய்யப்படுகிறது.\n\n(4) பிராணாயாமா: ரெசகா (மூச்சு விட்டுவிடுதல்) உலகத்தை உருவாக்கும் பொருட்களிலிருந்து பெயர் மற்றும் வடிவத்தின் இரண்டு பொய்யான அம்சங்களை அகற்றுவது, புரகா (மூச்சு இழுத்தல்) அந்த பொருட்களில் நிலையான இருப்பு, விழிப்புணர்வு மற்றும் ஆனந்தத்தின் மூன்று உண்மையான அம்சங்களை பிடித்துக்கொள்வது, கும்பகா அந்த அம்சங்களை பிடித்துக்கொள்வது.\n\n(5) பிரத்யாஹாரா: பெயர் மற்றும் வடிவம் மனத்தில் மீண்டும் நுழையாமல் தடுப்பது.\n\n(6) தாரணா: மனத்தை இதயத்தில் வெளியே திரும்பாமல் வைத்திருப்பது, மற்றும் ஒருவர் சுயமாக இருப்பதை உணர்வது, இருப்பு-விழிப்புணர்வு-ஆனந்தம்.\n\n(7) தியானம்: ‘நான் தூய விழிப்புணர்வே’ என்ற வடிவில் தியானம். அதாவது, ஐந்து உறைகளால் கூடிய உடலை விட்டுவிட்டு, ‘நான் யார்?’ என்று விசாரித்து, அதன் விளைவாக சுயமாக பிரகாசிக்கும் ‘நான்’ இல் நிலைத்திருப்பது. இந்த விஜ்ஞானம் சுயம் அல்லது அசுயத்திற்கு மட்டுமே தொடர்புடையது, மற்றும் அதுவாகவே வெளிப்படும். சுயத்துடன் தொடர்புடைய போது, அது உண்மையான அறிவு, சுயத்தின் பொருள் கொண்ட மன மோடு, அல்லது ஒருங்கிணைந்த (சுயம்) கொண்ட அறிவு என்று அழைக்கப்படுகிறது; மற்றும் அசுயத்துடன் தொடர்புடைய போது, அது அறியாமை என்று அழைக்கப்படுகிறது. சுயத்துடன் தொடர்புடைய மற்றும் சுயத்தின் வடிவில் வெளிப்படும் இந்த விஜ்ஞானத்தின் நிலை, உண்மையான (சுயம்) இன் நேரடி அனுபவத்திற்கான அடையாளமாகும். ஆனால் இது தானே சுயத்தின் நிலையை உருவாக்காது. அதன் மூலம் இந்த வெளிப்பாடு நிகழ்கிறது, அது பிரஜ்ஞானம் என்று அழைக்கப்படும் அடிப்படை யதார்த்தம். வேத உரை ‘பிரஜ்ஞானம் பிரம்மா’ அதே உண்மையை கற்பிக்கிறது.\n\nநீங்கள் அதை வேதத்தின் பொருளாக அறிந்துகொள்ளுங்கள். சுயம் சுய ஒளி மற்றும் எல்லாவற்றின் சாட்சியாக விஜ்ஞானகோஷத்தில் வசிப்பதாக வெளிப்படுகிறது.\n\nஒருங்கிணைந்த மன மோடு அதை உன் இலக்காக பிடித்து சுயமாக அனுபவி.'
    )
  ],
);
